const BASE_TOYS = [
  'TOY_01_KNIFE_SWITCH',
  'TOY_02_CONFIDENCE_PNEUMATIC',
  'TOY_06_FUSE_WIRE_SNIPPER',
];

function g(category, difficulty, canonicalEntityKey, stem, choices, answerIdx, ahaFactoid, extra = {}) {
  const supportedToys = [...BASE_TOYS];
  if (extra.numeric) supportedToys.push('TOY_03_VERNIER_DIAL', 'TOY_10_CLIFFHANGERS_THROTTLE');
  if (extra.geo) supportedToys.push('TOY_05_RELIEF_GLOBE_3D');
  return {
    isPrimeTimeGold: true,
    category,
    difficulty,
    canonicalEntityKey,
    stem,
    choices,
    answerIdx,
    ahaFactoid,
    supportedToys,
    ...extra,
  };
}

